function roundLesson(){
  const mistake=game.state.lastMistake,context=mistake?.context||game.state.context,content=CONTENT.find(item=>item.id===mistake?.contentId),name=content?.label||'dieses Signal';
  const text=mistake?mistake.kind==='useful'?`„${name}“ war gerade hilfreich. ${context==='gaming'?'Team-Absprachen und deine Zeitgrenze unterstützen eine bewusste Gaming-Pause.':context==='sleep'?'Ruhe-Signale helfen dir, deinen digitalen Tag bewusst abzuschließen.':'Schulsachen und echte Pausen unterstützen dein Lernziel.'} Schau vor dem Wischen kurz auf die Situation.`:context==='sleep'?`„${name}“ wollte deine Aufmerksamkeit vor dem Schlafen binden. Autoplay und „noch ein Match“ machen das Aufhören schwerer. Ein bewusstes Ende schafft Platz für Ruhe.`:context==='gaming'?`„${name}“ hat deine geplante Spielzeit unterbrochen. Gaming darf Spaß machen; unnötige Unterbrechungen und endlose Verlängerungen passen trotzdem nicht zu jedem Ziel.`:`„${name}“ hat deine Lernzeit unterbrochen. Beim Wechseln zwischen Aufgabe und Benachrichtigung brauchst du Zeit, um wieder hineinzufinden. Schütze einen Fokus-Abschnitt und mach danach eine echte Pause.`:'Du hast passende Signale erkannt. Digitale Inhalte sind nicht pauschal gut oder schlecht: Entscheidend ist, ob sie gerade zu deinem Ziel passen. Behalte das auch im nächsten Raum bei.';
  return `<aside class="round-lesson"><div>${ninjaPortrait()}</div><section><small>NIMs Lernmoment</small><p>${escape(text)}</p></section></aside>`;
}
