  dialog('Die Ninja-Rangliste',`${controls}<p id="leaderboard-status" class="leaderboard-status" role="status">${escape(message)}</p>${rows?`<ol class="leaderboard-list">${rows}</ol>`:''}<div class="leaderboard-share"><h3>Deinen letzten Run teilen</h3><p class="muted">Nur wenn du auf „Run veröffentlichen“ klickst, werden dein Ninja-Name und Ergebnis öffentlich in die Rangliste übertragen. Nur Open Runs zählen für die gemeinsame Rangliste. Alle spielen mit denselben drei Herzen und langsamem Einstieg ohne gekaufte Fähigkeiten oder Supers. Ältere Open-Runs zählen nicht in dieser neuen Wertung. Ein Gerätewechsel übernimmt dein Profil nicht.</p><div class="leaderboard-actions">${button('Aktualisieren','refresh-leaderboard','ghost')+button('Run veröffentlichen','submit-score','primary')}</div></div><p class="muted">Deine persönlichen Rekorde findest du weiterhin unter ${button('Meine Rekorde','highscores','ghost')}.</p>`, '',{label:'GEMEINSAM SPIELEN · SCORE VERGLEICHEN',classes:'leaderboard-panel'});
  const enabled=leaderboard.getStatus().configured&&!leaderboardBusy&&game.state.mode==='open'&&game.state.ended&&game.state.result==='lives'&&game.state.credited&&game.state.openRuleset==='open-v2'&&!game.state.isTutorial;$('overlay-root').querySelector('[data-action="submit-score"]').disabled=!enabled;
  $('overlay-root').querySelector('[data-action="refresh-leaderboard"]').disabled=leaderboardBusy;
