function unlockCatalog(type,ref){const items={skill:SKILLS,world:WORLDS,background:BACKGROUNDS,skin:skinList(),achievement:ACHIEVEMENTS};return type==='level'?{name:`Level ${ref}`,description:'Deine guten Entscheidungen lassen deinen Ninja wachsen.'}:items[type]?.find(item=>item.id===ref);}
function unlockText(type,ref){const item=unlockCatalog(type,ref);if(!item)return null;const text=type==='skill'?`${item.description} ${item.type==='super'?'Rüste diese Super unten in deiner Sammlung aus. Gute Entscheidungen laden sie auf; bei 100 % tippe auf die Super-Taste.':'Die Fähigkeit wirkt ab deiner nächsten neuen Runde.'}`:type==='achievement'?`${item.description} Hol dir deine ${item.reward} Münzen unten bei den erreichten Erfolgen ab.`:type==='world'?`${item.description} Starte den Raum über deine Zimmerkarte.`:type==='background'?'Die neue Kulisse gehört dir! Wähle sie im Basar aus und starte eine neue Runde, um sie zu besuchen.':type==='skin'?'Dein neuer Look ist bereit. Wähle ihn im Ninja-Basar aus; auch deine Wischspur verändert sich.':item.description;return {title: type==='achievement'?`Geschafft: ${item.name}!`:type==='level'?`${item.name} erreicht!`:`${item.name} freigeschaltet!`,text};}
