    value.innerHTML=Array.from({length:max},(_,index)=>`<span class="heart-icon${index>=hearts?' is-empty':''}" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21.2l8.8-8.8a5.5 5.5 0 0 0 0-7.8Z"/></svg></span>`).join('')+`<span class="lives-count" aria-hidden="true">${hearts}/${max}</span>`;
